// Positions along a polyline, used to stand figures on a path.
export type Pt = [number, number]
export function resample(pts: Pt[], step = 2): Pt[] {
  const out: Pt[] = [pts[0]]
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i]
    const n = Math.max(1, Math.round(Math.hypot(b[0] - a[0], b[1] - a[1]) / step))
    for (let k = 1; k <= n; k++) out.push([a[0] + ((b[0] - a[0]) * k) / n, a[1] + ((b[1] - a[1]) * k) / n])
  }
  return out
}
export function walker(path: Pt[]) {
  const pts = resample(path)
  const cum = [0]
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]))
  return (s: number) => {
    let i = 1
    while (i < cum.length - 1 && cum[i] < s) i++
    const t = (s - cum[i - 1]) / (cum[i] - cum[i - 1] || 1)
    const a = pts[i - 1], b = pts[i]
    return { x: a[0] + (b[0] - a[0]) * t, y: a[1] + (b[1] - a[1]) * t, dir: Math.sign(b[0] - a[0]) || 1 }
  }
}
export function colours(ink: string, paper: string) {
  return { '--pa-ink': ink, '--pa-hole': paper, '--pa-red': '#DA291C', '--pa-brass': '#B08A3E' } as Record<string, string>
}
